class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def modify(root):
    def traverse(node, acc):
        if not node:
            return acc
        acc = traverse(node.right, acc)
        node.val += acc
        return traverse(node.left, node.val)

    traverse(root, 0)
    return root
